class Solution { void inorder(TreeNode* node,vector<int>& values){if(!node)return;inorder(node->left,values);values.push_back(node->val);inorder(node->right,values);}public:vector<int> getAllElements(TreeNode* root1,TreeNode* root2){vector<int> first,second,answer;inorder(root1,first);inorder(root2,second);int i=0,j=0;while(i<(int)first.size()||j<(int)second.size())if(j==(int)second.size()||(i<(int)first.size()&&first[i]<=second[j]))answer.push_back(first[i++]);else answer.push_back(second[j++]);return answer;} };
